public PooledConn borrow(long timeoutMs) throws InterruptedException, TimeoutException {
        long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(timeoutMs);
        while (true) {
            PooledConn conn = idle.poll();
            if (conn != null) {
                if (conn.isAlive() && !conn.isExpired(maxLifetimeMs)) return conn;
                totalCreated.decrementAndGet();
                conn.destroyQuietly();
                continue;
            }
            int cur = totalCreated.get();
            if (cur < maxSize && totalCreated.compareAndSet(cur, cur + 1)) {
                try { return new PooledConn(this); }
                catch (RuntimeException e) { totalCreated.decrementAndGet(); throw e; }
            }
            long rem = deadline - System.nanoTime();
            if (rem <= 0) throw new TimeoutException("Pool exhausted after " + timeoutMs + "ms");
            conn = idle.poll(rem, TimeUnit.NANOSECONDS);
            if (conn != null && conn.isAlive() && !conn.isExpired(maxLifetimeMs)) return conn;
            if (conn != null) { totalCreated.decrementAndGet(); conn.destroyQuietly(); }
        }
    }
}
